import React, { useState, useEffect, useRef, useCallback } from 'react';
import ContentModal from '../Common/ContentModal';
import './NutritionFeed.css';

const NutritionFeed = () => {
    const [posts, setPosts] = useState([]);
    const [showContentModal, setShowContentModal] = useState(false);
    const feedEndRef = useRef(null);

    useEffect(() => {
        const savedPosts = localStorage.getItem('nutritionFeedPosts');
        if (savedPosts) {
            setPosts(JSON.parse(savedPosts));
        } else {
            const initialPosts = [
                { id: 1, type: 'text', title: '🥗 Основы здорового питания', content: 'Правильное питание - основа здоровья. Узнайте о принципах сбалансированного рациона.', date: '2025-03-15', author: 'Admin' },
                { id: 2, type: 'text', title: '🍎 Польза фруктов', content: 'Фрукты - источник витаминов и минералов. Включайте их в свой ежедневный рацион.', date: '2025-03-16', author: 'Admin' }
            ];
            setPosts(initialPosts);
            localStorage.setItem('nutritionFeedPosts', JSON.stringify(initialPosts));
        }
    }, []);

    const demoRole = localStorage.getItem('demoRole');
    const isAdmin = demoRole === 'admin-moderator' || demoRole === 'admin-nutrition' || demoRole === 'developer' || demoRole === 'owner';

    const handleAddPost = () => {
        if (!isAdmin) {
            alert('Только администратор питания может добавлять записи');
            return;
        }
        setShowContentModal(true);
    };

    const handleSavePost = (data) => {
        const post = {
            id: Date.now(),
            type: data.mediaType || 'text',
            title: data.title,
            content: data.description,
            url: data.mediaUrl || '',
            date: new Date().toISOString().split('T')[0],
            author: 'Admin'
        };

        const updatedPosts = [...posts, post];
        setPosts(updatedPosts);
        localStorage.setItem('nutritionFeedPosts', JSON.stringify(updatedPosts));
        setShowContentModal(false);

        setTimeout(() => {
            if (feedEndRef.current) {
                feedEndRef.current.scrollIntoView({ behavior: 'smooth' });
            }
        }, 100);
    };

    const confirmDeletePost = (post) => {
        if (!isAdmin) {
            alert('Только администратор питания может удалять записи!');
            return;
        }
        const updatedPosts = posts.filter(p => p.id !== post.id);
        setPosts(updatedPosts);
        localStorage.setItem('nutritionFeedPosts', JSON.stringify(updatedPosts));
    };

    return (
        <div className="nutrition-feed-container">
            <div className="main-feed">
                <div className="feed-container">
                    <div className="feed-list">
                        {posts.map((post) => (
                            <div key={post.id} className="feed-post">
                                <div className="post-header">
                                    <div className="post-title">{post.title}</div>
                                    {isAdmin && (
                                        <button className="delete-post" onClick={() => confirmDeletePost(post)} title="Удалить запис">🗑️</button>
                                    )}
                                </div>
                                <div className="post-date">{post.date}</div>
                                <div className="post-content">{post.content}</div>

                                {post.type === 'audio' && post.url && (
                                    <div className="post-audio">
                                        <button className="play-audio-btn">▶️ Слушать аудио</button>
                                    </div>
                                )}

                                {post.type === 'video' && post.url && (
                                    <div className="post-video">
                                        <video controls width="100%">
                                            <source src={post.url} type="video/mp4" />
                                        </video>
                                    </div>
                                )}
                            </div>
                        ))}
                        <div ref={feedEndRef} />
                    </div>

                    {isAdmin && (
                        <div className="admin-section">
                            <div className="admin-panel">
                                <button className="add-post-btn" onClick={handleAddPost}>➕ Добавить запис</button>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <ContentModal
                isOpen={showContentModal}
                onClose={() => setShowContentModal(false)}
                onSave={handleSavePost}
                initialTitle=""
                initialDescription=""
            />
        </div>
    );
};

export default NutritionFeed;
